const input = $input.first().json.body || $input.first().json;
const rows = Array.isArray(input.rows) ? input.rows : [];

function parseBool(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'boolean') return value;
  const normalized = String(value).toLowerCase().trim();
  if (['true', '1', 'oui', 'yes'].includes(normalized)) return true;
  if (['false', '0', 'non', 'no'].includes(normalized)) return false;
  return fallback;
}

return [{
  json: {
    source: 'webhook',
    entity: input.entity || 'Banque - Direction financiere',
    report_period: input.report_period || new Date().toLocaleDateString('fr-FR'),
    currency: input.currency || 'FCFA',
    manager_email: input.manager_email || ($env.INTERNAL_REVIEW_EMAIL || 'controle.financier@sib.ci'),
    recipients: Array.isArray(input.recipients) && input.recipients.length ? input.recipients : ['controle.financier@sib.ci'],
    rules: {
      absolute_variation_threshold: Number(input.absolute_variation_threshold || 10000000),
      relative_variation_threshold: Number(input.relative_variation_threshold || 0.15)
    },
    rows: rows.map((row) => ({
      account_code: row.account_code || row.compte || '',
      account_label: row.account_label || row.libelle || '',
      current_amount: Number(row.current_amount || row.solde_actuel || 0),
      previous_amount: Number(row.previous_amount || row.solde_precedent || 0),
      support_required: parseBool(row.support_required ?? row.justificatif_requis, true),
      support_received: parseBool(row.support_received ?? row.justificatif_recu, false),
      owner: row.owner || row.responsable || 'Equipe finance'
    }))
  }
}];

const data = $input.first().json;
const rows = Array.isArray(data.rows) ? data.rows : [];
const absThreshold = Number(data.rules?.absolute_variation_threshold || 10000000);
const relThreshold = Number(data.rules?.relative_variation_threshold || 0.15);

function pct(current, previous) {
  if (!previous) return current === 0 ? 0 : 1;
  return (current - previous) / Math.abs(previous);
}

function formatMoney(value) {
  return new Intl.NumberFormat('fr-FR').format(Number(value || 0));
}

const anomalies = rows.map((row) => {
  const current = Number(row.current_amount || 0);
  const previous = Number(row.previous_amount || 0);
  const absoluteVariation = current - previous;
  const relativeVariation = pct(current, previous);
  const missingSupport = Boolean(row.support_required) && !Boolean(row.support_received);
  const thresholdBreach = Math.abs(absoluteVariation) >= absThreshold || Math.abs(relativeVariation) >= relThreshold;

  let severity = 'faible';
  if ((missingSupport && thresholdBreach) || Math.abs(relativeVariation) >= 0.4) {
    severity = 'elevee';
  } else if (missingSupport || thresholdBreach) {
    severity = 'moyenne';
  }

  return {
    ...row,
    absolute_variation: absoluteVariation,
    relative_variation: relativeVariation,
    missing_support: missingSupport,
    threshold_breach: thresholdBreach,
    severity,
    observation: [
      thresholdBreach ? `Variation de ${formatMoney(absoluteVariation)} ${data.currency || 'FCFA'} (${(relativeVariation * 100).toFixed(1)} %).` : null,
      missingSupport ? 'Justificatif manquant.' : null
    ].filter(Boolean).join(' ')
  };
}).filter((item) => item.threshold_breach || item.missing_support);

const priorityRank = { elevee: 3, moyenne: 2, faible: 1 };
anomalies.sort((a, b) => (priorityRank[b.severity] || 0) - (priorityRank[a.severity] || 0) || Math.abs(b.absolute_variation) - Math.abs(a.absolute_variation));

const grouped = {
  now: anomalies.filter((item) => item.severity === 'elevee'),
  review: anomalies.filter((item) => item.severity === 'moyenne'),
  wait: anomalies.filter((item) => item.severity === 'faible')
};

return [{
  json: {
    ...data,
    anomalies,
    anomaly_count: anomalies.length,
    high_priority_count: grouped.now.length,
    review_count: grouped.review.length,
    wait_count: grouped.wait.length,
    grouped,
    kpi: {
      rows_analyzed: rows.length,
      anomalies_detected: anomalies.length,
      high_priority_count: grouped.now.length,
      missing_support_count: anomalies.filter((item) => item.missing_support).length
    }
  }
}];

