const source = $('Detecter ecarts et priorites').first().json;
const raw = $input.first().json?.choices?.[0]?.message?.content || '{}';

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = {
    executive_summary: 'Une revue humaine est requise avant diffusion.',
    what_moved: [],
    review_now: [],
    can_wait: [],
    escalate_to_manager: [],
    managerial_comment: raw
  };
}

function list(items) {
  return (Array.isArray(items) ? items : []).map((item) => `<li>${String(item)}</li>`).join('') || '<li>Aucun point a signaler.</li>';
}

const html = `
<div style="font-family:Arial,sans-serif;max-width:760px;margin:0 auto;color:#1f2937">
  <h1 style="color:#163556">Synthese de pre-cloture bancaire</h1>
  <p><strong>Entite :</strong> ${source.entity}<br><strong>Periode :</strong> ${source.report_period}<br><strong>Anomalies detectees :</strong> ${source.anomaly_count}</p>
  <div style="background:#f8fafc;border:1px solid #dbe4ee;border-radius:8px;padding:16px;margin:16px 0">
    <strong>Resume executif</strong>
    <p>${parsed.executive_summary || ''}</p>
  </div>
  <h2 style="color:#163556">Ce qui a bouge</h2>
  <ul>${list(parsed.what_moved)}</ul>
  <h2 style="color:#163556">Ce qui doit etre revu maintenant</h2>
  <ul>${list(parsed.review_now)}</ul>
  <h2 style="color:#163556">Ce qui peut attendre</h2>
  <ul>${list(parsed.can_wait)}</ul>
  <h2 style="color:#163556">Ce qui doit remonter au manager</h2>
  <ul>${list(parsed.escalate_to_manager)}</ul>
  <h2 style="color:#163556">Commentaire manager</h2>
  <p>${parsed.managerial_comment || ''}</p>
  <hr style="margin:24px 0;border:none;border-top:1px solid #e5e7eb" />
  <p style="font-size:12px;color:#6b7280">Synthese preparee automatiquement. Validation humaine obligatoire avant tout usage officiel.</p>
</div>`;

return [{
  json: {
    ...source,
    ai_summary: parsed,
    summary_html: html,
    final_subject: `[Pre-cloture] Synthese ecarts - ${source.entity} - ${source.report_period}`
  }
}];

const data = $input.first().json;
const baseUrl = $env.N8N_BASE_URL || 'https://your-n8n.example.com';
const payload = {
  entity: data.entity,
  report_period: data.report_period,
  recipients: data.recipients,
  final_subject: data.final_subject,
  ai_summary: data.ai_summary,
  anomaly_count: data.anomaly_count,
  high_priority_count: data.high_priority_count,
  review_count: data.review_count,
  wait_count: data.wait_count
};

const encoded = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
const approveUrl = `${baseUrl}/webhook/pre-cloture-bancaire-approve?decision=approved&payload=${encoded}`;
const rejectUrl = `${baseUrl}/webhook/pre-cloture-bancaire-approve?decision=rejected&payload=${encoded}`;

const reviewHtml = `
<div style="font-family:Arial,sans-serif;max-width:760px;margin:0 auto;color:#1f2937">
  <h2 style="color:#163556">Validation requise - Synthese de pre-cloture bancaire</h2>
  <p><strong>Entite :</strong> ${data.entity}<br><strong>Periode :</strong> ${data.report_period}<br><strong>Anomalies :</strong> ${data.anomaly_count}</p>
  <p>Merci de valider la synthese avant diffusion officielle.</p>
  <p style="margin:24px 0">
    <a href="${approveUrl}" style="background:#059669;color:#ffffff;padding:12px 18px;border-radius:6px;text-decoration:none;font-weight:bold;margin-right:12px">Approuver et diffuser</a>
    <a href="${rejectUrl}" style="background:#dc2626;color:#ffffff;padding:12px 18px;border-radius:6px;text-decoration:none;font-weight:bold">Rejeter</a>
  </p>
  <div style="border:1px solid #dbe4ee;border-radius:8px;padding:16px;background:#f8fafc">
    ${data.summary_html}
  </div>
</div>`;

return [{
  json: {
    ...data,
    approval_payload: encoded,
    approve_url: approveUrl,
    reject_url: rejectUrl,
    review_html: reviewHtml
  }
}];

