const query = $input.first().json.query || $input.first().json;
const decision = String(query.decision || '').toLowerCase();
const encoded = String(query.payload || '');

let payload = {};
try {
  payload = JSON.parse(Buffer.from(encoded, 'base64url').toString('utf8'));
} catch (error) {
  payload = { decode_error: error.message };
}

return [{
  json: {
    decision,
    approved: decision === 'approved',
    ...payload
  }
}];

